// ModelGatewayServer is the server API for ModelGateway service.
// All implementations must embed UnimplementedModelGatewayServer
// for forward compatibility.
//
// ModelGateway — public boundary for HTTP/gRPC/SSE/WebSocket.
// Owns: auth verification, request normalization, rate limiting, usage envelopes.
// Does NOT own: session state, tool execution, or model routing decisions.
type ModelGatewayServer interface {
	// Unary invoke — synchronous request/response.
	Invoke(context.Context, *InvokeRequest) (*InvokeResponse, error)
	// Server-streaming invoke — returns chunks as they arrive from the model.
	InvokeStream(*InvokeRequest, grpc.ServerStreamingServer[InvokeChunk]) error
	// Fetch — full-fat web fetch through Quarry (JS rendering, TLS
	// fingerprint emulation, charset detection, soft-404, JSON-LD).
	// Replaces the dead Python web_fetch tool.
	Fetch(context.Context, *FetchRequest) (*FetchResponse, error)
	// ExtractStructured — fetch a URL via Quarry, then coerce the
	// page content into a caller-supplied JSON schema. The gateway
	// performs the fetch and forwards the (content, schema) tuple to
	// inference-core's existing structured_output_schema path. Replaces
	// the dead Python extract_structured tool. Firecrawl-equivalent.
	ExtractStructured(context.Context, *ExtractStructuredRequest) (*ExtractStructuredResponse, error)
	// WebSearch — proxy to Quarry's /v1/search. Replaces v2 web_search.
	// The edge handles SmartSearchRouter (Google/Bing/Tavily/local) and
	// returns ranked results; the gateway is just a typed pass-through
	// so callers don't need a Quarry client of their own.
	WebSearch(context.Context, *WebSearchRequest) (*WebSearchResponse, error)
	// Sleep — explicit pause inside an agent loop. Useful for poll-
	// backoff and waiting on async external state. Server-side enforced
	// so callers can't trivially exceed budget.
	Sleep(context.Context, *SleepRequest) (*SleepResponse, error)
	// RemoteTrigger — generic outbound HTTP webhook with SSRF guards.
	// Used by automations to ping internal services or third-party
	// webhooks. Routes through the same security envelope as Fetch.
	RemoteTrigger(context.Context, *RemoteTriggerRequest) (*RemoteTriggerResponse, error)
	// SendMessage — publish a typed message envelope onto NATS. Replaces
	// the v2 send_message tool. Subject namespaces are enforced server-
	// side so agents can't publish to arbitrary subjects.
	SendMessage(context.Context, *SendMessageRequest) (*SendMessageResponse, error)
	// SyntheticOutput — test/debug tool that echoes a fixed payload back
	// to the caller. Used by integration tests + smoke probes; production
	// builds may want to gate behind a feature flag.
	SyntheticOutput(context.Context, *SyntheticOutputRequest) (*SyntheticOutputResponse, error)
	// EnterPlanMode — switch a run into plan-collect mode. While in plan
	// mode, write-class tools (file_edit, file_write, bash, remote_trigger,
	// send_message) are gated by the approval queue; read-class tools
	// (fetch, web_search, extract_structured) flow normally.
	EnterPlanMode(context.Context, *EnterPlanModeRequest) (*EnterPlanModeResponse, error)
	// ExitPlanMode — leave plan mode. Pending actions in the plan are
	// discarded unless the caller explicitly approved them separately.
	ExitPlanMode(context.Context, *ExitPlanModeRequest) (*ExitPlanModeResponse, error)
	// IsPlanMode — read-only check used by tool dispatch middleware.
	IsPlanMode(context.Context, *IsPlanModeRequest) (*IsPlanModeResponse, error)
	// TeamCreate — assign a new worker task to the coordinator team.
	// Returns the worker id. Used in multi-agent runs to track parallel
	// sub-work.
	TeamCreate(context.Context, *TeamCreateRequest) (*TeamCreateResponse, error)
	// TeamDelete — mark a worker task as completed or failed. Required
	// so the coordinator knows the sub-work converged.
	TeamDelete(context.Context, *TeamDeleteRequest) (*TeamDeleteResponse, error)
	// TeamList — enumerate worker tasks for an org, optionally filtered
	// by state. Used by UIs + the coordinator agent's status checks.
	TeamList(context.Context, *TeamListRequest) (*TeamListResponse, error)
	// LspQuery — proxy LSP requests (diagnostics, hover, definition,
	// completion) to a configured LSP bridge. Returns Unimplemented when
	// `LSP_BRIDGE_URL` is unset. The bridge owns server lifecycle and
	// multi-language routing; the gateway is a typed pass-through so
	// agents don't need to know about the bridge's HTTP shape.
	LspQuery(context.Context, *LspQueryRequest) (*LspQueryResponse, error)
	// RequestApproval — register a pending approval for a risky action.
	// Returns immediately; resolution happens out-of-band via
	// ApproveApproval / DenyApproval. Used by the run-loop before
	// calling destructive tools.
	RequestApproval(context.Context, *RequestApprovalRequest) (*RequestApprovalResponse, error)
	// ApproveApproval — resolve a pending approval as approved.
	ApproveApproval(context.Context, *ApproveApprovalRequest) (*ApproveApprovalResponse, error)
	// DenyApproval — resolve a pending approval as denied.
	DenyApproval(context.Context, *DenyApprovalRequest) (*DenyApprovalResponse, error)
	// ListPendingApprovals — read pending approvals for a run. Used by
	// UIs surfacing the queue and by the run-loop polling for resolution.
	ListPendingApprovals(context.Context, *ListPendingApprovalsRequest) (*ListPendingApprovalsResponse, error)
	// RecordTrajectory — append a single run trajectory (goal + actions
	// + outcome) to the recorder. Fire-and-forget from the run-loop's
	// hot path. Records are kept in-memory (size-bounded) and published
	// to NATS so external pipelines can stream them.
	RecordTrajectory(context.Context, *RecordTrajectoryRequest) (*RecordTrajectoryResponse, error)
	// ListTrajectories — read recent trajectories for an org. Filtered
	// by outcome / pattern / time range. Capped at 500 per call.
	ListTrajectories(context.Context, *ListTrajectoriesRequest) (*ListTrajectoriesResponse, error)
	// ExportTrajectories — return trajectories as a JSONL-encoded blob
	// suitable for the Atropos RL training format. Returns inline bytes
	// when small; promote to MinIO upload in a future iteration.
	ExportTrajectories(context.Context, *ExportTrajectoriesRequest) (*ExportTrajectoriesResponse, error)
	// ===== Wave 10d — skills loader =====
	ListSkills(context.Context, *ListSkillsRequest) (*ListSkillsResponse, error)
	GetSkill(context.Context, *GetSkillRequest) (*GetSkillResponse, error)
	MatchSkills(context.Context, *MatchSkillsRequest) (*MatchSkillsResponse, error)
	// ===== Wave 10g — MCP server hosting =====
	RegisterMcpServer(context.Context, *RegisterMcpServerRequest) (*RegisterMcpServerResponse, error)
	ListMcpServers(context.Context, *ListMcpServersRequest) (*ListMcpServersResponse, error)
	ProxyMcpTool(context.Context, *ProxyMcpToolRequest) (*ProxyMcpToolResponse, error)
	// ===== Wave 10h — plugins =====
	RegisterPlugin(context.Context, *RegisterPluginRequest) (*RegisterPluginResponse, error)
	ListPlugins(context.Context, *ListPluginsRequest) (*ListPluginsResponse, error)
	SetPluginEnabled(context.Context, *SetPluginEnabledRequest) (*SetPluginEnabledResponse, error)
	// ===== Wave 10i — commands + hooks + permissions + policy =====
	ListCommands(context.Context, *ListCommandsRequest) (*ListCommandsResponse, error)
	ExecuteCommand(context.Context, *ExecuteCommandRequest) (*ExecuteCommandResponse, error)
	RegisterHook(context.Context, *RegisterHookRequest) (*RegisterHookResponse, error)
	ListHooks(context.Context, *ListHooksRequest) (*ListHooksResponse, error)
	CheckPermission(context.Context, *CheckPermissionRequest) (*CheckPermissionResponse, error)
	SetPermission(context.Context, *SetPermissionRequest) (*SetPermissionResponse, error)
	GetPolicy(context.Context, *GetPolicyRequest) (*GetPolicyResponse, error)
	SetPolicy(context.Context, *SetPolicyRequest) (*SetPolicyResponse, error)
	// ===== Wave 10j — messages + analytics + voice + tasks =====
	AppendThreadMessage(context.Context, *AppendThreadMessageRequest) (*AppendThreadMessageResponse, error)
	ListThreadMessages(context.Context, *ListThreadMessagesRequest) (*ListThreadMessagesResponse, error)
	GetAnalytics(context.Context, *GetAnalyticsRequest) (*GetAnalyticsResponse, error)
	TextToSpeech(context.Context, *TextToSpeechRequest) (*TextToSpeechResponse, error)
	SpeechToText(context.Context, *SpeechToTextRequest) (*SpeechToTextResponse, error)
	CreateTask(context.Context, *CreateTaskRequest) (*CreateTaskResponse, error)
	ListTasks(context.Context, *ListTasksRequest) (*ListTasksResponse, error)
	// Health check for load balancer probes.
	Health(context.Context, *HealthRequest) (*HealthResponse, error)
	mustEmbedUnimplementedModelGatewayServer()
}

